        date: 0,
        title: "Nekuyan",
        originalTitle: "女装してめんどくさい事になってるネクラとヤンキーの両片想い",
        otherTitle:  "Josou-shite Mendokusai Koto ni Natteru Nekura to Yankee no Ryou Kataomoi - Crossplay Love: Otaku x Punk",
        class: "Shōnen",
        genre: ["Comédie","Romance","Slice of Life"],
